import type { AiProvider } from "./types";

export interface ModelInfo {
  id: string;
  tier: "lite" | "low" | "medium" | "high" | "pro";
  light: boolean;
}

export const MODEL_TIER_COLORS: Record<ModelInfo["tier"], string> = {
  lite: "#22c55e",
  low: "#3b82f6",
  medium: "#f59e0b",
  high: "#f97316",
  pro: "#9333ea"
};

export const PROVIDER_MODELS: Record<AiProvider, ModelInfo[]> = {
  openai: [
    { id: "gpt-4.1-mini", tier: "lite", light: true },
    { id: "gpt-4.1-nano", tier: "lite", light: true },
    { id: "gpt-4o-mini", tier: "low", light: true },
    { id: "gpt-oss-120b-medium", tier: "medium", light: false }
  ],
  gemini: [
    { id: "gemini-3.5-flash-lite", tier: "lite", light: true },
    { id: "gemini-3.6-flash-high", tier: "high", light: false },
    { id: "gemini-3.6-flash-medium", tier: "medium", light: false },
    { id: "gemini-3.6-flash-low", tier: "low", light: true },
    { id: "gemini-3.5-flash-high", tier: "high", light: false },
    { id: "gemini-3.5-flash-medium", tier: "medium", light: false },
    { id: "gemini-3.5-flash-low", tier: "low", light: true },
    { id: "gemini-3.1-pro-high", tier: "pro", light: false },
    { id: "gemini-3.1-pro-low", tier: "pro", light: false }
  ],
  claude: [
    { id: "claude-3-5-haiku-latest", tier: "lite", light: true },
    { id: "claude-sonnet-4.6-thinking", tier: "medium", light: false },
    { id: "claude-opus-4.6-thinking", tier: "pro", light: false }
  ],
  ollama: [
    { id: "gpt-oss-120b-medium", tier: "medium", light: false },
    { id: "llama3.1", tier: "low", light: true },
    { id: "mistral", tier: "low", light: true },
    { id: "qwen2.5", tier: "low", light: true }
  ]
};

export const DEFAULT_PROVIDER_MODEL: Record<AiProvider, string> = {
  openai: "gpt-4.1-mini",
  gemini: "gemini-3.5-flash-lite",
  claude: "claude-3-5-haiku-latest",
  ollama: "gpt-oss-120b-medium"
};

export const DEFAULT_MODEL_BY_PROVIDER = DEFAULT_PROVIDER_MODEL;

export function getModelInfo(provider: AiProvider, modelId: string): ModelInfo | undefined {
  return PROVIDER_MODELS[provider].find((model) => model.id === modelId);
}

export function getModelDotColor(provider: AiProvider, modelId: string): string {
  const info = getModelInfo(provider, modelId);
  return info ? MODEL_TIER_COLORS[info.tier] : "#64748b";
}

export function getModelColor(modelId: string, provider: AiProvider): string {
  return getModelDotColor(provider, modelId);
}

export function getProviderModels(provider: AiProvider, lightOnly = false): ModelInfo[] {
  const models = PROVIDER_MODELS[provider];
  return lightOnly ? models.filter((model) => model.light) : models;
}

export function getProviderModelIds(provider: AiProvider): string[] {
  return PROVIDER_MODELS[provider].map((model) => model.id);
}
